{"chunk_id":"8ec495","wall_time_seconds":0.2549157,"exit_code":0,"original_token_count":566,"output":"#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 1e6 + 5, M = 25;

int n, m, k, r, x[N], idx[N], p[N], ans, res;
vector<int> vec[N];
struct node
{
	int mx, mn;

	const friend node operator+(const node &x, const node &y) { return {max(x.mx, y.mx), min(x.mn, y.mn)}; }

} st[M][N];

int calc(int l, int r)
{
	int k = __lg(r - l + 1);
	node res = st[k][l] + st[k][r - (1 << k) + 1];
	return res.mx - res.mn;
}

void del()
{}

void init() {}

void solve()
{
	cin >> n >> k >> r;
	for (int i = 1; i <= n; ++i)
		cin >> st[0][i].mx, st[0][i].mn = st[0][i].mx;
	for (int j = 1; j <= __lg(n); ++j)
	{
		for (int i = 1; i + (1 << j) - 1 <= n; ++i)
			st[j][i] = st[j - 1][i] + st[j - 1][i + (1 << (j - 1))];
	}
	for (int i = 2; i <= n; ++i)
	{
		x[i] = x[i - 1];
		if (st[0][i].mx > st[0][i - 1].mx)
			++x[i];
		if (st[0][i].mx < st[0][i - 1].mx)
			--x[i];
		idx[++m] = x[i];
	}
	idx[++m] = 0;
	sort(idx + 1, idx + m + 1);
	m = unique(idx + 1, idx + m + 1) - idx - 1;
	for (int i = 1; i <= n; ++i)
	{
		x[i] = lower_bound(idx + 1, idx + m + 1, x[i]) - idx;
		vec[x[i]].push_back(i);
	}
	for (int i = 1, t = 1, j = 1, v; i <= n; ++i)
	{
		if (idx[x[j]] > idx[x[i]] + r)
			j = vec[x[j] - 1][p[x[j] - 1]];
		if (idx[x[j]] < idx[x[i]] - r)
			j = vec[x[j] + 1][p[x[j] + 1]];
		v = lower_bound(idx + 1, idx + m + 1, idx[x[i]] + r) - idx;
		if (v <= m && idx[v] == idx[x[i]] + r && p[v] < (int)vec[v].size())
			j = min(j, vec[v][p[v]]);
		v = lower_bound(idx + 1, idx + m + 1, idx[x[i]] - r) - idx;
		if (v <= m && idx[v] == idx[x[i]] - r && p[v] < (int)vec[v].size())
			j = min(j, vec[v][p[v]]);
		while (t <= i && calc(t, i) > k)
		{
			++p[x[t]];
			if (t == j)
			{
				if (idx[x[i]] - r <= idx[x[j + 1]] && idx[x[j + 1]] <= idx[x[i]] + r)
					++j;
				else
					j = vec[x[j]][p[x[j]]];
			}
			++t;
		}
		if (i - j + 1 > ans)
		{
			ans = i - j + 1;
			res = j;
		}
	}
	cout << ans << ' ' << res << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	freopen("stock.in", "r", stdin);
	freopen("stock.out", "w", stdout);
	int _ = 1;
	init();
	while (_--)
		solve();
	return 0;
}

