#define main stock_main
#include "stock.cpp"
#undef main
int main() {
    int tests = 0;
    for (int len = 1, pow3 = 3; len <= 7; ++len, pow3 *= 3) {
        for (int mask = 0; mask < pow3; ++mask) {
            int a[8] = {}, h[8] = {};
            for (int i = 1, z = mask; i <= len; ++i, z /= 3) {
                a[i] = z % 3;
                if (i > 1) h[i] = h[i-1] + (a[i] > a[i-1]) - (a[i] < a[i-1]);
            }
            for (int P = 0; P <= 2; ++P) for (int Q = 0; Q < len; ++Q) {
                std::stringstream input, output;
                input << len << ' ' << P << ' ' << Q;
                for (int i = 1; i <= len; ++i) input << ' ' << a[i];
                auto cinbuf = cin.rdbuf(input.rdbuf());
                auto coutbuf = cout.rdbuf(output.rdbuf());
                solve();
                cin.rdbuf(cinbuf); cout.rdbuf(coutbuf);
                int best = 0, left = 0;
                for (int l = 1; l <= len; ++l) for (int u = l; u <= len; ++u) {
                    auto mm = minmax_element(a+l,a+u+1);
                    if (*mm.second-*mm.first <= P && abs(h[u]-h[l]) <= Q && u-l+1 > best) {best=u-l+1; left=l;}
                }
                if(output.str() != to_string(best)+" "+to_string(left)+"\n") {cerr<<input.str(); return 1;}
                for(int v=1;v<=m;++v) {vec[v].clear();p[v]=0;}
                x[1]=0; m=ans=res=0; ++tests;
            }
        }
    }
    cout << tests << endl;
}

